import { formHelperTextClasses } from '@mui/material/FormHelperText';
import { inputAdornmentClasses } from '@mui/material/InputAdornment';
import { inputLabelClasses } from '@mui/material/InputLabel';
import { outlinedInputClasses } from '@mui/material/OutlinedInput';
import type { SxProps, Theme } from '@mui/material/styles';
import type { SystemStyleObject } from '@mui/system';
import { svTokens } from '../../theme/tokens';

export const fieldRootStyles: SxProps<Theme> = {
  gap: '4px',
  minWidth: 0,
  maxWidth: '100%',
  fontFamily: 'fontFamily',
};
export function fieldLabelStyles(theme: Theme): SystemStyleObject<Theme> {
  return {
    position: 'static',
    transform: 'none',
    transition: 'none',
    maxWidth: '100%',
    fontSize: '12px',
    lineHeight: '16px',
    fontWeight: 500,
    whiteSpace: 'normal',
    overflowWrap: 'anywhere',
    color: `var(--SvField-secondary, ${(theme.vars ?? theme).palette.text.secondary})`,
    [`&.${inputLabelClasses.focused}, &.${inputLabelClasses.error}, &.${inputLabelClasses.disabled}`]:
      {
        color: `var(--SvField-secondary, ${(theme.vars ?? theme).palette.text.secondary})`,
      },
  };
}
export function fieldHelperStyles(theme: Theme): SystemStyleObject<Theme> {
  return {
    margin: 0,
    fontSize: '12px',
    lineHeight: '16px',
    overflowWrap: 'anywhere',
    color: `var(--SvField-secondary, ${(theme.vars ?? theme).palette.text.secondary})`,
    [`&.${formHelperTextClasses.error}`]: {
      color: `var(--SvField-error, ${(theme.vars ?? theme).palette.error.main})`,
    },
    [`&.${formHelperTextClasses.disabled}`]: {
      color: `var(--SvField-secondary, ${(theme.vars ?? theme).palette.text.secondary})`,
    },
  };
}
export function fieldInputStyles(theme: Theme): SystemStyleObject<Theme> {
  const palette = (theme.vars ?? theme).palette;
  const secondary = `var(--SvField-secondary, ${palette.text.secondary})`;
  const outline = `& .${outlinedInputClasses.notchedOutline}`;
  return {
    borderRadius: '8px',
    minHeight: '36px',
    padding: '4px 6px 4px 8px',
    gap: '8px',
    fontSize: '13px',
    lineHeight: '24px',
    letterSpacing: '-0.0025em',
    color: 'text.primary',
    backgroundColor: 'transparent',
    [outline]: {
      top: 0,
      borderWidth: '1px',
      borderColor: `var(--SvField-stroke, ${svTokens(theme).stroke})`,
      '& legend': { display: 'none' },
    },
    [`&:hover:not(.${outlinedInputClasses.disabled}):not(.${outlinedInputClasses.error}) .${outlinedInputClasses.notchedOutline}, &.${outlinedInputClasses.focused}:not(.${outlinedInputClasses.disabled}):not(.${outlinedInputClasses.error}) .${outlinedInputClasses.notchedOutline}`]:
      {
        borderWidth: '1px',
        borderColor: `var(--SvField-accent, ${svTokens(theme).accent})`,
      },
    [`&.${outlinedInputClasses.error} .${outlinedInputClasses.notchedOutline}`]:
      {
        borderWidth: '1px',
        borderColor: `var(--SvField-error, ${palette.error.main})`,
      },
    [`&.${outlinedInputClasses.disabled} .${outlinedInputClasses.notchedOutline}`]:
      {
        borderColor: `var(--SvField-stroke, ${svTokens(theme).stroke})`,
      },
    '&:has(input:focus-visible), &:has(textarea:focus-visible)': {
      outline: `2px solid ${svTokens(theme).focus}`,
      outlineOffset: '2px',
    },
    [`& .${outlinedInputClasses.input}`]: {
      minWidth: 0,
      padding: '2px 0',
      height: '24px',
      lineHeight: '24px',
      '&::placeholder': { color: secondary, opacity: 1 },
      [`&.${outlinedInputClasses.disabled}`]: {
        WebkitTextFillColor: secondary,
        color: secondary,
        opacity: 1,
      },
    },
    [`&.${outlinedInputClasses.multiline}`]: { alignItems: 'flex-start' },
    [`&.${outlinedInputClasses.multiline} .${outlinedInputClasses.input}`]: {
      height: 'auto',
    },
    [`& .${inputAdornmentClasses.root}`]: {
      margin: 0,
      gap: '4px',
      maxHeight: 'none',
      flexShrink: 0,
      color: secondary,
    },
  };
}
